#include <vector>
#include <memory>

// std::allocator satisfies interchangeability
using DefaultVec = std::vector<int>;

int main() {
    DefaultVec v1(10, 5);
    DefaultVec v2(std::move(v1)); // Fast move is possible
    // Storage allocated by v1's internal allocator
    // is correctly deallocated by v2's internal allocator.

    // If custom allocators were used, this depends on 
    // propagate_on_container_move_assignment and equality comparison.
}
